CREATE INDEX IF NOT EXISTS idx_medicines_search_compound 
            ON medicines(status, name, pinyin_name, chinese_name, english_name) 
            WHERE status = 'active';

CREATE INDEX IF NOT EXISTS idx_medicines_category_status 
            ON medicines(category, status) 
            WHERE status = 'active';

CREATE INDEX IF NOT EXISTS idx_medicines_price_range 
            ON medicines(base_price, status) 
            WHERE status = 'active';
